#ifndef HG_ABOUT_TEXT_H
#define HG_ABOUT_TEXT_H
#define HG_ABOUT_HELP_W L"HGFloater help\r\n" L"\r\n" L"This is the short help: what each window is, and the keys and gestures that drive it. The full manual, with pictures, is on the web: https://rubidus-api.github.io/hgfloater/\r\n" L"\r\n" L"== Start here ==\r\n" L"\r\n" L"• The floater is the small box with the clock that stays on top. Click it, or press Win + Alt + Space from anywhere, to open the taskbox.\r\n" L"• The taskbox is the dashboard: your running windows, your shortcuts and ten buttons, in one grid. Move the pointer away and it folds back into the floater after half a second.\r\n" L"• To add a shortcut, point at Set, choose Open Shortcuts Folder, and copy any .lnk or .url into that folder. The icon appears within a second. A shortcut to a folder goes to the Dir list instead. Icons are sorted by file name: 0001 Editor.lnk, 0002 Browser.lnk.\r\n" L"• To quit, press Ctrl + Q, or choose Exit hgfloater in the Set list.\r\n" L"\r\n" L"Only one copy runs at a time. HGFloater has no installer and no service, never reaches the network, and keeps everything in %USERPROFILE%\\.HellGates\\hgfloater\\.\r\n" L"\r\n" L"== The floater ==\r\n" L"\r\n" L"  Click — Opens or closes the taskbox.\r\n" L"  Drag, or Alt + drag — Moves it anywhere, the taskbar included; on the taskbar it stays on top.\r\n" L"  Alt + wheel — Opacity.\r\n" L"  Ctrl + wheel, or Ctrl + drag — Size of the whole floater.\r\n" L"  Alt + arrows or WASD — Moves it from the keyboard.\r\n" L"  T — Opens the taskbox.\r\n" L"  C, Ctrl + E — Opens the command box.\r\n" L"  F1 — This help.\r\n" L"\r\n" L"The lines under the clock are bars for CPU, temperature (TMP), GPU, memory and battery, with the reading at the right. A row the machine does not report is left out. show_stats=0 in config.ini hides them.\r\n" L"\r\n" L"Both clock lines are formats you write, in the strftime notation: the clock is %H:%M and the date %a, %b %-d by default. Change them in the settings window under Floater Clock.\r\n" L"\r\n" L"  %H\r\n" L"      Shows: hour, 00-23\r\n" L"      Code: %I\r\n" L"      Shows: hour, 01-12\r\n" L"  %M\r\n" L"      Shows: minute, 00-59\r\n" L"      Code: %S\r\n" L"      Shows: second, 00-59\r\n" L"  %p\r\n" L"      Shows: AM or PM\r\n" L"      Code: %j\r\n" L"      Shows: day of the year\r\n" L"  %Y\r\n" L"      Shows: year, 2026\r\n" L"      Code: %y\r\n" L"      Shows: year, 26\r\n" L"  %m\r\n" L"      Shows: month, 01-12\r\n" L"      Code: %d\r\n" L"      Shows: day, 01-31\r\n" L"  %b\r\n" L"      Shows: Jan\r\n" L"      Code: %B\r\n" L"      Shows: January\r\n" L"  %a\r\n" L"      Shows: Sun\r\n" L"      Code: %A\r\n" L"      Shows: Sunday\r\n" L"  %e\r\n" L"      Shows: day, space-padded\r\n" L"      Code: %%\r\n" L"      Shows: a percent sign\r\n" L"\r\n" L"A minus drops the padding: %-d is 6 where %d is 06.\r\n" L"\r\n" L"== The taskbox ==\r\n" L"\r\n" L"  Click an icon, or Space on it — Brings the window forward, or launches the shortcut.\r\n" L"  Right-click, or Enter / F2 — The icon's menu: Run, Focus, Close Window, Open File Location.\r\n" L"  Drag a task icon — Moves it in the grid.\r\n" L"  Arrows or WASD — Move between icons.\r\n" L"  Shift + 0-9 — The window with that badge (S0-S9).\r\n" L"  Shift + A-Z — The shortcut with that badge (SA-SZ).\r\n" L"  Drag a border — Changes the grid; it snaps to whole columns.\r\n" L"  Ctrl + wheel, Ctrl + + / - — Icon and text size.\r\n" L"  Alt + wheel, Alt + + / - — Opacity.\r\n" L"  Ctrl + R / 0, F5 — Resets position, size and opacity.\r\n" L"  Esc — Hides the taskbox and re-reads the shortcuts folder.\r\n" L"\r\n" L"Badges show on the icon under the pointer, on the one with the keyboard focus, and on every icon while Shift, Ctrl or Alt is held.\r\n" L"\r\n" L"Pointing at a task icon outlines its window on the desktop without raising it. With Show Tabs as Task Icons on, pointing at a browser, Explorer, Terminal or Notepad icon lists its tabs beside it.\r\n" L"\r\n" L"The status line at the top shows the last message, then the time. Drag it to move the taskbox; right-click it for the A/V Control Center.\r\n" L"\r\n" L"== The buttons ==\r\n" L"\r\n" L"  A/V\r\n" L"      Click: The A/V Control Center\r\n" L"  Vol\r\n" L"      Click: Mute and unmute\r\n" L"      Wheel: Volume, 5% a notch\r\n" L"      Right-click: A/V Control Center, Audio\r\n" L"  Mon\r\n" L"      Click: Scaling of this screen\r\n" L"      Wheel: Brightness, 10% a notch\r\n" L"      Right-click: A/V Control Center, Display\r\n" L"  Alp\r\n" L"      Wheel: Taskbox opacity\r\n" L"  Dir\r\n" L"      Click: Folder shortcuts, as a list\r\n" L"  Set\r\n" L"      Click: Every switch, the settings window, Exit\r\n" L"  Clip\r\n" L"      Click: Clipboard history\r\n" L"  Note\r\n" L"      Click: The note list\r\n" L"  Cmd\r\n" L"      Click: The command box\r\n" L"  D\r\n" L"      Click: Shows the desktop; again to restore\r\n" L"\r\n" L"Dir and Set open when pointed at; A/V waits for a click. On Vol, Mon and Alp, PageUp / PageDown or E / Q turn the value from the keyboard.\r\n" L"\r\n" L"In the Dir, Set and tab lists: 1-9 and 0 jump to a row, Up / Down or Tab step in, Enter or Space takes the row, Left / Right leave the list (on a number row they turn the value), Esc steps out.\r\n" L"\r\n" L"== The A/V Control Center ==\r\n" L"\r\n" L"A/V, Ctrl + O in the taskbox, or a right-click on the status line, Vol or Mon. The left pane lists what can be set; the right pane holds its controls:\r\n" L"\r\n" L"• Output & Volume: the master volume, Mute Output, and the output devices.\r\n" L"• Screen Topology: the four Win + P arrangements.\r\n" L"• A display: Preview Window (a live thumbnail you can click through), Brightness, Scale and Resolution.\r\n" L"\r\n" L"Esc, Ctrl + W or a click outside closes it.\r\n" L"\r\n" L"== The command box ==\r\n" L"\r\n" L"Cmd, C or Ctrl + E. Type a command and press Enter.\r\n" L"\r\n" L"  Enter — Runs what is typed.\r\n" L"  Shift + Enter — A new line; several lines run in order.\r\n" L"  Ctrl + H — History mode: pick an earlier line with Up / Down, Enter.\r\n" L"  Ctrl + S — Scroll mode: Up / Down a line, Left / Right a page.\r\n" L"  Ctrl + Space — Back to the input box.\r\n" L"  Esc — Leaves the mode, or closes the box and returns to the taskbox.\r\n" L"  Ctrl + W — Closes the box.\r\n" L"\r\n" L"  help\r\n" L"      Short: h\r\n" L"      What it does: Every command. help move explains one.\r\n" L"  help key\r\n" L"      Short: h k\r\n" L"      What it does: The keys of this box.\r\n" L"  show\r\n" L"      Short: s\r\n" L"      What it does: Windows, numbered.\r\n" L"  go 1\r\n" L"      What it does: Focus window 1.\r\n" L"  move 1 100 100 2\r\n" L"      Short: m 1 100 100 2\r\n" L"      What it does: Move window 1 to 100, 100 on display 2.\r\n" L"  resize 1 1\r\n" L"      Short: r 1 1\r\n" L"      What it does: Resize window 1 to preset 1 (show resize lists them).\r\n" L"  find windows word\r\n" L"      Short: f w word\r\n" L"      What it does: Windows whose title holds word.\r\n" L"  show tabs, go tab 4\r\n" L"      Short: s t, g t 4\r\n" L"      What it does: Every tab, and switch to one.\r\n" L"  show monitor 1\r\n" L"      Short: s m 1\r\n" L"      What it does: Display 1's preview, on and off.\r\n" L"  note, note new, note 3\r\n" L"      Short: n, n n, n 3\r\n" L"      What it does: The note list, a new note, note 3.\r\n" L"  find note word\r\n" L"      Short: f n word\r\n" L"      What it does: Notes that hold word.\r\n" L"  clipboard 3\r\n" L"      Short: b 3\r\n" L"      What it does: Make clip 3 the current one.\r\n" L"  show option, write option 1 on\r\n" L"      Short: s o, w o 1 on\r\n" L"      What it does: The switches, and set one.\r\n" L"  show value, write value 1 60\r\n" L"      Short: s v, w v 1 60\r\n" L"      What it does: The values, and set one.\r\n" L"  show key, bind, unbind\r\n" L"      Short: s k\r\n" L"      What it does: The keys, and change them.\r\n" L"  show sensors\r\n" L"      Short: s s\r\n" L"      What it does: Every temperature sensor found.\r\n" L"  settings\r\n" L"      Short: set\r\n" L"      What it does: The settings window.\r\n" L"  config\r\n" L"      Short: c\r\n" L"      What it does: config.ini in Notepad.\r\n" L"  clear\r\n" L"      Short: cls\r\n" L"      What it does: Empties the transcript.\r\n" L"\r\n" L"== Notes ==\r\n" L"\r\n" L"Note, N or Ctrl + N in the taskbox, or note in the command box. Each note is a plain .txt file; its first line is the title. Saving is automatic.\r\n" L"\r\n" L"  Enter, double-click — Opens the note in its own editor.\r\n" L"  Insert, the Add button — A new note.\r\n" L"  Space, a click on the box — Checks the note.\r\n" L"  K, the Arc button — Archives the checked notes, or restores them.\r\n" L"  Delete, the Del button — Deletes the checked notes, to the Recycle Bin.\r\n" L"  The Search button — Shows only notes that hold every word typed.\r\n" L"  Drag a row by its grip — Puts it elsewhere; that half turns to the Manual sort.\r\n" L"  Right-click — Open, Archive or Restore, Delete, and Sort by.\r\n" L"  Ctrl + wheel — Note text size, shared by the list and every editor.\r\n" L"  Alt + arrows, Ctrl + arrows — Move, resize the list window.\r\n" L"  Esc, Ctrl + W — Closes the list or the editor.\r\n" L"\r\n" L"An archived note opens read-only until it is restored. In an editor, Ctrl + Z and Ctrl + Y undo and redo a hundred steps.\r\n" L"\r\n" L"== The clipboard history ==\r\n" L"\r\n" L"Clip or Ctrl + L. It lists the text you copied, newest first, kept in memory only: nothing is written to disk, and quitting empties it.\r\n" L"\r\n" L"  Click, Enter — Makes that clip the current one; the window stays open.\r\n" L"  Right-click — Copy to Clipboard, Delete, Delete All.\r\n" L"  Del — Deletes the selected clip.\r\n" L"  The search box — Shows only clips that contain the text.\r\n" L"  The number box — The most clips kept, 16 by default.\r\n" L"\r\n" L"== The settings window ==\r\n" L"\r\n" L"Ctrl + ,, Settings Window... in the Set list, or settings. One list, with a filter box at the top (Ctrl + F): Options, Floater Clock, Fonts, Values, Window Colours and Keys. Every change takes effect and is saved at once.\r\n" L"\r\n" L"• Enter or Space flips a switch, opens a font or colour chooser, or edits a clock format.\r\n" L"• Left / Right change a value.\r\n" L"• R puts a row back to its default.\r\n" L"• Under Keys, Enter on a function adds the next chord you press, and Del removes one.\r\n" L"\r\n" L"== Keys anywhere in HGFloater ==\r\n" L"\r\n" L"  Win + Alt + Space — Shows or hides the taskbox, from anywhere.\r\n" L"  Ctrl + , — The settings window.\r\n" L"  F1 — This help.\r\n" L"  Ctrl + W — Closes a note, the note list, the clipboard history, the command box or this window.\r\n" L"  Ctrl + Q — Quits.\r\n" L"\r\n" L"The note windows, the clipboard history and the command box keep the usual editing keys (Ctrl + X, C, V, Z, Y, A) for the text.\r\n" L"\r\n" L"== Files ==\r\n" L"\r\n" L"  %USERPROFILE%\\.HellGates\\hgfloater\\config.ini — Every setting, plain INI.\r\n" L"  %USERPROFILE%\\.HellGates\\hgfloater\\shortcuts\\ — Your .lnk and .url files.\r\n" L"  %USERPROFILE%\\.HellGates\\hgfloater\\note\\ — One .txt per note, and note.ini.\r\n" L"\r\n" L"Edit config.ini while HGFloater is closed; a deleted key comes back with its default at the next start. The only thing written outside this folder is the Run value of Start with Windows, and only while it is on.\r\n" L"\r\n" L"The configuration file, every command and every key are described in full in the manual: https://rubidus-api.github.io/hgfloater/\r\n"
#endif